INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.settings.users.create.sendInvitationTooltip', 'fr-FR', 'Lorsqu''activé, un e-mail d''invitation sera envoyé à l''utilisateur. Celui-ci définira son propre mot de passe via une page d''accueil sécurisée. Le champ de mot de passe ci-dessus devient facultatif — s''il est laissé vide, un espace réservé aléatoire est défini dans le fournisseur d''identité et l''utilisateur le définit lors du premier accès.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
