INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.is_admin', 'fr-FR', 'L''indicateur d''administrateur d''identité permet à l''utilisateur d''accéder au système IDP pour effectuer des modifications de niveau administratif, mais n''accorde pas de droits d''administration à cette application. Pour accorder des accès d''administration à l''application, définissez les rôles applicatifs.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
