INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.is_verified', 'fr-FR', 'Indique si le processus de vérification de l''identité a été mené à bien. Il peut dépendre d''un processus KYC ou d''un autre type de vérification.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
